INSERT INTO iniciativa (cod_iniciativa, nombre_iniciativa, descripcion, solucion, resultados_esperados, documentos, codigo_postulacion, id_tipo_iniciativa) VALUES
(1, 'Gestión energética 001', 'Proyecto para optimizar consumo energético institucional en una organización externa.', 'Plataforma de medición y alertas con validación en terreno y seguimiento institucional.', 'Reducción de costos y reportes mensuales y evidencia para toma de decisiones.', 'carpeta_tecnica_001.pdf; carta_apoyo_001.pdf', 5001, 1),
(2, 'Monitoreo hídrico 002', 'Proyecto para controlar variables de calidad de agua en una organización externa.', 'Sensores conectados y tablero web con validación en terreno y seguimiento institucional.', 'Mejor trazabilidad ambiental y evidencia para toma de decisiones.', 'carpeta_tecnica_002.pdf; carta_apoyo_002.pdf', 5002, 2),
(3, 'Analítica logística 003', 'Proyecto para mejorar rutas de distribución regional en una organización externa.', 'Modelo predictivo con datos históricos con validación en terreno y seguimiento institucional.', 'Menores tiempos de despacho y evidencia para toma de decisiones.', 'carpeta_tecnica_003.pdf; carta_apoyo_003.pdf', 5003, 1),
(4, 'Salud digital 004', 'Proyecto para apoyar atención remota en comunidades en una organización externa.', 'Sistema de turnos y seguimiento con validación en terreno y seguimiento institucional.', 'Mayor cobertura territorial y evidencia para toma de decisiones.', 'carpeta_tecnica_004.pdf; carta_apoyo_004.pdf', 5004, 2),
(5, 'Ciberseguridad pyme 005', 'Proyecto para elevar madurez de seguridad operacional en una organización externa.', 'Diagnóstico y plan de mitigación con validación en terreno y seguimiento institucional.', 'Menor exposición a incidentes y evidencia para toma de decisiones.', 'carpeta_tecnica_005.pdf; carta_apoyo_005.pdf', 5005, 1),
(6, 'Agricultura inteligente 006', 'Proyecto para automatizar variables de cultivo en una organización externa.', 'Riego guiado por sensores con validación en terreno y seguimiento institucional.', 'Uso eficiente de recursos y evidencia para toma de decisiones.', 'carpeta_tecnica_006.pdf; carta_apoyo_006.pdf', 5006, 2),
(7, 'Educación inmersiva 007', 'Proyecto para fortalecer aprendizaje práctico en una organización externa.', 'Módulos virtuales interactivos con validación en terreno y seguimiento institucional.', 'Mejora en retención de contenidos y evidencia para toma de decisiones.', 'carpeta_tecnica_007.pdf; carta_apoyo_007.pdf', 5007, 1),
(8, 'Economía circular 008', 'Proyecto para reducir residuos de procesos productivos en una organización externa.', 'Sistema de clasificación y reutilización con validación en terreno y seguimiento institucional.', 'Disminución de residuos enviados y evidencia para toma de decisiones.', 'carpeta_tecnica_008.pdf; carta_apoyo_008.pdf', 5008, 2),
(9, 'Movilidad segura 009', 'Proyecto para ordenar flujos de transporte interno en una organización externa.', 'Aplicación de monitoreo y señalización con validación en terreno y seguimiento institucional.', 'Mejor seguridad operacional y evidencia para toma de decisiones.', 'carpeta_tecnica_009.pdf; carta_apoyo_009.pdf', 5009, 1),
(10, 'Trazabilidad productiva 010', 'Proyecto para registrar procesos críticos de producción en una organización externa.', 'Integración de códigos y base de datos con validación en terreno y seguimiento institucional.', 'Auditorías más rápidas y evidencia para toma de decisiones.', 'carpeta_tecnica_010.pdf; carta_apoyo_010.pdf', 5010, 2),
(11, 'Robótica aplicada 011', 'Proyecto para automatizar tareas repetitivas en una organización externa.', 'Prototipo robótico modular con validación en terreno y seguimiento institucional.', 'Aumento de productividad y evidencia para toma de decisiones.', 'carpeta_tecnica_011.pdf; carta_apoyo_011.pdf', 5011, 1),
(12, 'Turismo inteligente 012', 'Proyecto para mejorar experiencia de visitantes en una organización externa.', 'Mapa digital con recomendaciones con validación en terreno y seguimiento institucional.', 'Mayor interacción con destinos y evidencia para toma de decisiones.', 'carpeta_tecnica_012.pdf; carta_apoyo_012.pdf', 5012, 2),
(13, 'Minería sustentable 013', 'Proyecto para monitorear indicadores operacionales en una organización externa.', 'Dashboard de indicadores ambientales con validación en terreno y seguimiento institucional.', 'Decisiones con datos consolidados y evidencia para toma de decisiones.', 'carpeta_tecnica_013.pdf; carta_apoyo_013.pdf', 5013, 1),
(14, 'Manufactura flexible 014', 'Proyecto para adaptar líneas a baja escala en una organización externa.', 'Sistema de planificación de producción con validación en terreno y seguimiento institucional.', 'Mayor flexibilidad operativa y evidencia para toma de decisiones.', 'carpeta_tecnica_014.pdf; carta_apoyo_014.pdf', 5014, 2),
(15, 'Finanzas inclusivas 015', 'Proyecto para apoyar gestión financiera de mipymes en una organización externa.', 'Herramienta simple de control con validación en terreno y seguimiento institucional.', 'Mejor planificación de caja y evidencia para toma de decisiones.', 'carpeta_tecnica_015.pdf; carta_apoyo_015.pdf', 5015, 1),
